def save(name: str, age: int, subscribed: bool, output_file: str) -> dict:
    """When Save is pressed, write the JSON object {'name': <the name text>,…"""
    if not name or age is None or not isinstance(age, int):
        return {"status": "Name must be given and Age must be a whole number"}
    status = "Saved" if subscribed else "Not subscribed"
    try:
        with open(output_file, 'w') as file:
            file.write(f'{"name": "{name}", "age": {age}, "subscribed": {subscribed}}')
    except Exception as e:
        raise ValueError(f"Failed to save: {str(e)}")
    return {"status": status}
